if (msg.req.files && msg.req.files.length > 0) {
    var file = msg.req.files[0];

    // 1. Extraer Auth y Params
    // groupId viene en el cuerpo del multipart (msg.req.body) porque 'http in' de Node-RED parsea los campos de texto ahí.
    msg.group_id = (msg.req.body && msg.req.body.groupId) ? msg.req.body.groupId : "default";
    msg.session_id = msg.req.headers['x-session-id'];

    // Guardar los datos originales de la imagen para recuperarlos después de /detect
    msg.original_image_data = {
        buffer: file.buffer,
        filename: file.originalname,
        mimetype: file.mimetype
    };

    msg.payload = {
        "image": {
            "value": file.buffer,
            "options": {
                "filename": file.originalname,
                "contentType": file.mimetype
            }
        }
    };
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';
} else {
    msg.payload = {};
}
return msg;

msg.payload = { error: msg.error ? msg.error.message : 'Unknown error' };
msg.statusCode = 500;
return msg;

const TH = flow.get('face_threshold') ?? 0.5;
const p = msg.payload || {};
const score = Number(p.score);

if (Number.isNaN(score)) {
    msg.error = { code: 'NO_SCORE', message: 'Missing/invalid score' };
    msg.status = 400;
    return [null, msg];
}

msg.metrics = {
    first_model_score: score,
    threshold: TH
};

if (score >= TH) {
    msg.route = 'to_uniface';
    return [msg, null];
}

msg.route = 'skip_uniface';
msg.result = {
    recognized: false,
    reason: 'score_below_threshold',
    score
};
msg.status = 200;
return [null, msg];

// Recuperar imagen original guardada
if (msg.original_image_data) {
    msg.payload = {
        "image": {
            "value": msg.original_image_data.buffer,
            "options": {
                "filename": msg.original_image_data.filename,
                "contentType": msg.original_image_data.mimetype
            }
        }
    };
    // Limpiar headers anteriores y forzar multipart
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';
} else {
   // Fallback si no hay imagen (error?)
   msg.payload = {};
}

// No necesitamos Authorization por ahora si es local
// const token = flow.get('uniface_token');
// msg.headers['Authorization'] = ...

return msg;

// Normaliza la respuesta del microservicio
const t = msg._t0 || Date.now();
const latency = Date.now() - t;
const resp = msg.payload || {};
const pf = resp.primary_face || {};
let embeddingBase64 = null;
if (resp.embedding && Array.isArray(resp.embedding)) {
    const floatArray = new Float32Array(resp.embedding);
    const buffer = Buffer.from(floatArray.buffer);
    embeddingBase64 = buffer.toString('base64');
}

// 2. Configurar llamada REST
if (embeddingBase64) {
    msg.payload = {
        embeddingBase64: embeddingBase64,
        minSim: 0.4,
        top: 5
    };

    // Headers
    msg.headers = {};
    msg.headers['Content-Type'] = 'application/json';
    if (msg.session_id) {
        msg.headers['X-Session-Id'] = msg.session_id;
    }

    // URL endpoint Java
    msg.url = `http://localhost:8080/garAItu/group/${msg.group_id}/recognize`;

    msg.metrics = msg.metrics || {};
    msg.metrics.uniface_latency_ms = latency;
    msg.local_result = { recognized: !!resp.recognized, primary_face: pf };

    // SALIDA 1: Al REST
    return [msg, null];
} else {
    // Si no hubo cara, no llamamos al REST. Respondemos directo.
    msg.payload = { recognized: false, reason: "No embedding generated" };

    msg.metrics = msg.metrics || {};
    msg.metrics.uniface_latency_ms = latency;
    msg.local_result = { recognized: false, primary_face: pf };

    // SALIDA 2: Directo a Response
    return [null, msg];
}
